con=sqlite3.connect('file:/home/jeremy/.config/Cursor/User/globalStorage/state.vscdb?mode=ro', uri=True)
cut=1792972800000
best=None
inwin=0
time_keys=set()
for key, val in con.execute("select key, value from cursorDiskKV where key like 'composerData:%'"):
    if isinstance(val, bytes):
        val=val.decode('utf-8','replace')
    try:
        o=json.loads(val)
    except Exception:
        continue
    times=[]
    def walk(x, path=''):
        if isinstance(x, dict):
            for k,v in x.items():
                lk=k.lower()
                if any(s in lk for s in ('time','at','date','updated','created')) and (isinstance(v,(int,float)) or (isinstance(v,str) and v[:4] in ('2026','2025'))):
                    time_keys.add(k)
                    times.append((k,v))
                elif isinstance(v,(dict,list)) and path.count('.')<2:
                    walk(v, path+'.'+k)
        elif isinstance(x, list) and x and path.count('.')<2:
            walk(x[0], path+'[]')
    walk(o)
    nums=[]
    for k,v in times:
        if isinstance(v,(int,float)):
            n=v/1000 if v>1e12 else v
            nums.append(n)
    mx=max(nums) if nums else 0
    if mx>=1792972800:
        inwin+=1
    if best is None or mx>best[0]:
