#!/usr/bin/env python3
"""Collect local agent conversations and tool use since 2026-10-26 UTC.

Writes a private archive at /srv/git/odbus-verified/hackathon2026.
Transcript text is copied with light secret redaction. Credential files
and database credential tables are not copied.
"""

from __future__ import annotations

import json
import os
import re
import sqlite3
import time
from collections import Counter, defaultdict
from pathlib import Path

CUTOFF = 1792972800  # 2026-10-26 00:00:00 UTC
CUTOFF_MS = CUTOFF * 1000
OUT = Path("/srv/git/odbus-verified/hackathon2026")
HOME = Path("/home/jeremy")

TOOL_TYPES = {
    "tool_use",
    "tool_result",
    "tool_started",
    "tool_completed",
    "tool_call",
    "tool_call_result",
    "function_call",
    "function_call_output",
    "local_shell_call",
    "web_search_call",
    "custom_tool_call",
    "mcp_tool_call",
}

REDACTIONS = [
    (
        re.compile(
            r"(?i)(api[_-]?key|token|password|secret|authorization)\s*[:=]\s*['\"]?([^\s'\"]+)"
        ),
        r"\1=***",
    ),
    (re.compile(r"sk-or-v1-[a-zA-Z0-9_-]{10,}"), "sk-or-v1-***"),
    (re.compile(r"sk-[a-zA-Z0-9_-]{10,}"), "sk-***"),
    (
        re.compile(
            r"-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----"
        ),
        "[REDACTED PRIVATE KEY]",
    ),
    (
        re.compile(
            r'(?i)(\\?"[a-z_]*(?:private_?key|secret|password|passwd|token|api_?key|'
            r"sealed_?id|credential|shortids?)[a-z_]*\\?\"\s*:\s*\\?\")([^\"\\]+)"
        ),
        r"\1***",
    ),
    (
        re.compile(r"\b(?:SID1|OIA1|U0lEMQ|T0lBMQ)[A-Za-z0-9+/=_.:-]{16,}"),
        "[REDACTED CREDENTIAL]",
    ),
    (
        re.compile(r"(?i)(authorization|x-api-key|api-key)\s*[:=]\s*\S+"),
        r"\1: ***",
    ),
]


def redact(text: str) -> str:
    out = text
    for pattern, repl in REDACTIONS:
        out = pattern.sub(repl, out)
    return out


def iso(ts: float | None) -> str | None:
    if ts is None:
        return None
    try:
        return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))
    except (OverflowError, OSError, ValueError):
        return None


def note_ts(value, acc: dict) -> None:
    if isinstance(value, str):
        if len(value) >= 20 and value[0:4] == "2026" and "T" in value[10:12]:
            acc_ts = value
            if acc["first_raw"] is None or acc_ts < acc["first_raw"]:
                acc["first_raw"] = acc_ts
            if acc["last_raw"] is None or acc_ts > acc["last_raw"]:
                acc["last_raw"] = acc_ts
        return
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        n = float(value)
        if n > 1e12:
            n /= 1000.0
        if 1700000000 < n < 2000000000:
            if acc["first_epoch"] is None or n < acc["first_epoch"]:
                acc["first_epoch"] = n
            if acc["last_epoch"] is None or n > acc["last_epoch"]:
                acc["last_epoch"] = n


def tool_name(obj: dict) -> str | None:
    for key in ("name", "tool_name", "toolName", "tool", "method"):
        value = obj.get(key)
        if isinstance(value, str) and value and len(value) < 160:
            return value
    return None


def walk_obj(obj, acc: dict, depth: int = 0) -> None:
    if depth > 8:
        return
    if isinstance(obj, dict):
        kind = obj.get("type")
        if isinstance(kind, str) and (
            kind in TOOL_TYPES or "tool" in kind.lower() or kind.endswith("_call")
        ):
            acc["tools"] += 1
            name = tool_name(obj)
            if name:
                acc["names"][name] += 1
        calls = obj.get("tool_calls") or obj.get("toolCalls")
        if isinstance(calls, list):
            acc["tools"] += len(calls)
            for call in calls:
                if isinstance(call, dict):
                    name = tool_name(call)
                    fn = call.get("function")
                    if name is None and isinstance(fn, dict):
                        name = tool_name(fn)
                    if name:
                        acc["names"][name] += 1
        for key in (
            "timestamp",
            "created_at",
            "createdAt",
            "time",
            "lastUpdatedAt",
            "updatedAt",
        ):
            if key in obj:
                note_ts(obj[key], acc)
        for value in obj.values():
            if isinstance(value, (dict, list)):
                walk_obj(value, acc, depth + 1)
    elif isinstance(obj, list):
        for item in obj:
            if isinstance(item, (dict, list)):
                walk_obj(item, acc, depth + 1)


def new_acc() -> dict:
    return {
        "records": 0,
        "tools": 0,
        "names": Counter(),
        "first_raw": None,
        "last_raw": None,
        "first_epoch": None,
        "last_epoch": None,
        "bytes": 0,
    }


def span(acc: dict) -> tuple[str | None, str | None]:
    first = acc["first_raw"] or iso(acc["first_epoch"])
    last = acc["last_raw"] or iso(acc["last_epoch"])
    return first, last


def denied(path: Path) -> bool:
    name = path.name.lower()
    if name.endswith(".lock") or ".lock." in name:
        return True
    if path.suffix.lower() in {".pem", ".key", ".p12", ".sqlite", ".db", ".wal", ".shm"}:
        return True
    markers = (
        "auth.json",
        "credential",
        "credentials",
        ".env",
        "oauth",
        "cookie",
        "secret",
        "id_rsa",
        "id_ed25519",
    )
    return any(marker in name for marker in markers)


def copy_text(src: Path, dest: Path, acc: dict, parse_jsonl: bool) -> None:
    dest.parent.mkdir(parents=True, exist_ok=True)
    tmp = dest.with_suffix(dest.suffix + ".partial")
    with src.open("r", errors="replace") as inp, tmp.open("w", encoding="utf-8") as out:
        for line in inp:
            red = redact(line)
            out.write(red)
            acc["bytes"] += len(red.encode("utf-8", "replace"))
            if not parse_jsonl:
                acc["records"] += 1
                continue
            stripped = line.strip()
            if not stripped:
                continue
            acc["records"] += 1
            try:
                obj = json.loads(stripped)
            except json.JSONDecodeError:
                continue
            walk_obj(obj, acc)
    os.chmod(tmp, 0o600)
    tmp.replace(dest)


def rel_under(path: Path, root: Path) -> Path:
    try:
        return path.relative_to(root)
    except ValueError:
        return Path(path.name)


class Archive:
    def __init__(self) -> None:
        self.rows: list[dict] = []
        self.names: dict[str, Counter] = defaultdict(Counter)
        self.gaps: list[dict] = []
        self.files = 0
        self.bytes = 0

    def add_row(self, source: str, kind: str, origin: str, archive: str, acc: dict, extra: dict | None = None) -> None:
        first, last = span(acc)
        row = {
            "source": source,
            "kind": kind,
            "origin": origin,
            "archive": archive,
            "bytes": acc["bytes"],
            "records": acc["records"],
            "tool_events": acc["tools"],
            "first": first,
            "last": last,
        }
        if extra:
            row.update(extra)
        self.rows.append(row)
        self.names[source].update(acc["names"])
        self.files += 1
        self.bytes += acc["bytes"]

    def copy_file(self, source: str, src: Path, dest_rel: str, kind: str, parse_jsonl: bool) -> None:
        if not src.is_file() or denied(src):
            return
        if src.stat().st_size > 800_000_000:
            self.gaps.append(
                {"source": source, "path": str(src), "reason": "skipped file larger than 800MB"}
            )
            return
        dest = OUT / dest_rel
        acc = new_acc()
        copy_text(src, dest, acc, parse_jsonl)
        self.add_row(source, kind, str(src), dest_rel, acc)

    def mtime_ok(self, path: Path) -> bool:
        try:
            return path.stat().st_mtime >= CUTOFF
        except OSError:
            return False


def collect_grok(arc: Archive) -> None:
    root = HOME / ".grok" / "sessions"
    wanted = {
        "chat_history.jsonl",
        "events.jsonl",
        "updates.jsonl",
        "rewind_points.jsonl",
        "summary.json",
    }
    session_dirs: set[Path] = set()
    if root.is_dir():
        for dirpath, dirnames, filenames in os.walk(root):
            dirnames[:] = [d for d in dirnames if d not in {"node_modules", "terminal"}]
            parent = Path(dirpath)
            for name in filenames:
                if name in wanted and arc.mtime_ok(parent / name):
                    session_dirs.add(parent)
    copied = 0
    for parent in sorted(session_dirs):
        for name in sorted(wanted):
            src = parent / name
            if not src.is_file():
                continue
            dest = Path("grok") / rel_under(src, root)
            arc.copy_file("grok", src, str(dest), name, name.endswith(".jsonl"))
            copied += 1
    sandbox = root / "sandbox-events.jsonl"
    if sandbox.is_file() and arc.mtime_ok(sandbox):
        arc.copy_file("grok", sandbox, "grok/sandbox-events.jsonl", "sandbox-events", True)
    arc.gaps.append(
        {
            "source": "grok",
            "reason": f"{len(session_dirs)} session directories had files written on or after 2026-10-26; {copied} conversation/tool files copied",
        }
    )


def collect_jsonl_tree(arc: Archive, source: str, root: Path, dest_root: str) -> int:
    count = 0
    if not root.is_dir():
        arc.gaps.append({"source": source, "path": str(root), "reason": "store missing"})
        return 0
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if d not in {"node_modules", ".git", "Cache"}]
        for name in filenames:
            if not name.endswith(".jsonl"):
                continue
            src = Path(dirpath) / name
            if denied(src) or not arc.mtime_ok(src):
                continue
            dest = Path(dest_root) / rel_under(src, root)
            arc.copy_file(source, src, str(dest), "jsonl", True)
            count += 1
    return count


def collect_junie(arc: Archive) -> None:
    root = HOME / ".junie" / "sessions"
    if not root.is_dir():
        arc.gaps.append({"source": "junie", "reason": "sessions directory missing"})
        return
    kept = 0
    for child in sorted(root.iterdir()):
        if not child.is_dir() or not child.name.startswith("session-"):
            continue
        parts = child.name.split("-")
        if len(parts) < 2 or parts[1] < "261026":
            continue
        transcript = child / "transcript.md"
        if transcript.is_file():
            arc.copy_file(
                "junie",
                transcript,
                f"junie/{child.name}/transcript.md",
                "transcript.md",
                False,
            )
            kept += 1
        elif not any(child.iterdir()):
            continue
        else:
            arc.gaps.append(
                {"source": "junie", "path": str(child), "reason": "session in window has no transcript.md"}
            )
    history = HOME / ".junie" / "history.jsonl"
    if history.is_file() and arc.mtime_ok(history):
        arc.copy_file("junie", history, "junie/history.jsonl", "history", True)
    arc.gaps.append({"source": "junie", "reason": f"{kept} transcripts from session ids dated 2026-10-26 or later"})


def collect_hermes(arc: Archive) -> None:
    db = HOME / ".hermes" / "state.db"
    if not db.is_file():
        arc.gaps.append({"source": "hermes", "reason": "state.db missing"})
        return
    out_dir = OUT / "hermes" / "sessions"
    out_dir.mkdir(parents=True, exist_ok=True)
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    sessions = list(
        con.execute(
            """
            SELECT s.id, s.source, s.display_name, s.model, s.started_at, s.ended_at
            FROM sessions s
            WHERE EXISTS (
              SELECT 1 FROM messages m
              WHERE m.session_id = s.id AND m.timestamp >= ?
            )
            ORDER BY s.started_at
            """,
            (CUTOFF,),
        )
    )
    for session in sessions:
        sid = session["id"]
        dest = out_dir / f"{sid}.jsonl"
        acc = new_acc()
        with dest.open("w", encoding="utf-8") as out:
            header = {
                "type": "session",
                "id": sid,
                "source": session["source"],
                "display_name": session["display_name"],
                "model": session["model"],
                "started_at": session["started_at"],
                "ended_at": session["ended_at"],
            }
            line = redact(json.dumps(header, default=str) + "\n")
            out.write(line)
            acc["bytes"] += len(line.encode())
            acc["records"] += 1
            note_ts(session["started_at"], acc)
            for message in con.execute(
                """
                SELECT id, role, content, tool_call_id, tool_calls, tool_name,
                       timestamp, finish_reason
                FROM messages
                WHERE session_id = ? AND timestamp >= ?
                ORDER BY timestamp, id
                """,
                (sid, CUTOFF),
            ):
                payload = {key: message[key] for key in message.keys()}
                raw_calls = payload.get("tool_calls")
                if isinstance(raw_calls, str):
                    try:
                        payload["tool_calls"] = json.loads(raw_calls)
                    except json.JSONDecodeError:
                        pass
                line = redact(json.dumps(payload, default=str) + "\n")
                out.write(line)
                acc["bytes"] += len(line.encode())
                acc["records"] += 1
                walk_obj(payload, acc)
                if payload.get("tool_name"):
                    acc["tools"] += 1
                    acc["names"][str(payload["tool_name"])] += 1
                note_ts(payload.get("timestamp"), acc)
        os.chmod(dest, 0o600)
        arc.add_row(
            "hermes",
            "session",
            str(db),
            str(dest.relative_to(OUT)),
            acc,
            {"session_id": sid, "title": session["display_name"]},
        )
    dumps = HOME / ".hermes" / "sessions"
    dump_count = 0
    if dumps.is_dir():
        for path in sorted(dumps.glob("request_dump_*.json")):
            if arc.mtime_ok(path):
                arc.copy_file(
                    "hermes",
                    path,
                    f"hermes/request-dumps/{path.name}",
                    "request_dump",
                    False,
                )
                dump_count += 1
    arc.gaps.append(
        {
            "source": "hermes",
            "reason": f"{len(sessions)} sessions with messages on or after cutoff; {dump_count} request dumps copied. System prompt bodies were not copied.",
        }
    )


def composer_epochs(obj) -> list[float]:
    found: list[float] = []

    def walk(value, depth: int) -> None:
        if depth > 5:
            return
        if isinstance(value, dict):
            for key, item in value.items():
                if key in {
                    "createdAt",
                    "lastUpdatedAt",
                    "lastReadAtMs",
                    "conversationCheckpointLastUpdatedAt",
                    "unfinishedRunAt",
                } and isinstance(item, (int, float)):
                    n = float(item)
                    found.append(n / 1000.0 if n > 1e12 else n)
                elif isinstance(item, (dict, list)):
                    walk(item, depth + 1)
        elif isinstance(value, list):
            for item in value[:30]:
                walk(item, depth + 1)

    walk(obj, 0)
    return found


def collect_cursor_db(arc: Archive) -> None:
    db = HOME / ".config" / "Cursor" / "User" / "globalStorage" / "state.vscdb"
    if not db.is_file():
        arc.gaps.append({"source": "cursor", "reason": "global state.vscdb missing"})
        return
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    chosen: dict[str, dict] = {}
    for key, value in con.execute(
        "SELECT key, value FROM cursorDiskKV WHERE key LIKE 'composerData:%'"
    ):
        if isinstance(value, bytes):
            value = value.decode("utf-8", "replace")
        try:
            obj = json.loads(value)
        except json.JSONDecodeError:
            continue
        epochs = [n for n in composer_epochs(obj) if n > 1700000000]
        if not epochs or max(epochs) < CUTOFF:
            continue
        cid = key.split("composerData:", 1)[1]
        chosen[cid] = obj
    out_dir = OUT / "cursor" / "composers"
    for cid, obj in sorted(chosen.items()):
        dest = out_dir / cid / "composer.jsonl"
        dest.parent.mkdir(parents=True, exist_ok=True)
        acc = new_acc()
        with dest.open("w", encoding="utf-8") as out:
            header = {
                "type": "composer",
                "composerId": obj.get("composerId") or cid,
                "name": obj.get("name"),
                "createdAt": obj.get("createdAt"),
                "lastUpdatedAt": obj.get("lastUpdatedAt"),
                "isAgentic": obj.get("isAgentic"),
            }
            line = redact(json.dumps(header, default=str) + "\n")
            out.write(line)
            acc["records"] += 1
            acc["bytes"] += len(line.encode())
            walk_obj(header, acc)
            like = f"bubbleId:{cid}:%"
            for bkey, raw in con.execute(
                "SELECT key, value FROM cursorDiskKV WHERE key LIKE ?",
                (like,),
            ):
                if isinstance(raw, bytes):
                    raw = raw.decode("utf-8", "replace")
                try:
                    bubble = json.loads(raw)
                except json.JSONDecodeError:
                    bubble = {"raw": raw[:2000]}
                record = {"type": "bubble", "key": bkey, "bubble": bubble}
                line = redact(json.dumps(record, default=str) + "\n")
                out.write(line)
                acc["records"] += 1
                acc["bytes"] += len(line.encode())
                walk_obj(record, acc)
        os.chmod(dest, 0o600)
        arc.add_row("cursor", "composer", str(db), str(dest.relative_to(OUT)), acc, {"composer_id": cid, "title": obj.get("name")})
    arc.gaps.append(
        {
            "source": "cursor",
            "reason": f"{len(chosen)} composer records in global state.vscdb have a timestamp on or after 2026-10-26. The 1.6GB database itself was not copied.",
        }
    )


def collect_sqlite_absence(arc: Archive) -> None:
    for source, db in (
        ("opencode", HOME / ".local/share/opencode/opencode.db"),
        ("kilo", HOME / ".local/share/kilo/kilo.db"),
    ):
        if not db.is_file():
            arc.gaps.append({"source": source, "reason": "database missing"})
            continue
        con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
        count = con.execute(
            "SELECT count(*) FROM session WHERE time_updated >= ?",
            (CUTOFF_MS,),
        ).fetchone()[0]
        latest = con.execute("SELECT max(time_updated) FROM session").fetchone()[0]
        arc.gaps.append(
            {
                "source": source,
                "reason": f"{count} sessions updated on or after cutoff. Latest session update {iso((latest or 0) / 1000.0)}. Database not copied because it contains a credential table.",
            }
        )


def collect_checked_empty(arc: Archive) -> None:
    checks = [
        ("factory", HOME / ".factory" / "sessions", "*.jsonl"),
        ("pi", HOME / ".pi" / "agent" / "sessions", "*.jsonl"),
        ("paseo", HOME / ".paseo" / "agent-requests", "*.json"),
        ("aider", HOME / ".aider", "*.md"),
    ]
    for source, root, pattern in checks:
        if not root.exists():
            arc.gaps.append({"source": source, "reason": f"missing {root}"})
            continue
        found = 0
        for path in root.rglob(pattern):
            if path.is_file() and arc.mtime_ok(path):
                found += 1
        arc.gaps.append(
            {"source": source, "reason": f"{found} {pattern} files written on or after cutoff under {root}"}
        )
    tool_history = HOME / ".claude-server-commander" / "tool-history.jsonl"
    if tool_history.is_file():
        arc.gaps.append(
            {
                "source": "claude-server-commander",
                "reason": f"tool-history.jsonl mtime {iso(tool_history.stat().st_mtime)}; included only if that is on or after cutoff",
            }
        )
        if arc.mtime_ok(tool_history):
            arc.copy_file(
                "claude-server-commander",
                tool_history,
                "claude-server-commander/tool-history.jsonl",
                "tool-history",
                True,
            )
    for label, path in (
        ("root-codex", Path("/root/.codex")),
        ("root-claude", Path("/root/.claude")),
        ("root-grok", Path("/root/.grok")),
        ("3tched-claude", Path("/home/3tched/.claude")),
        ("3tched-codex", Path("/home/3tched/.codex")),
        ("3tched-grok", Path("/home/3tched/.grok")),
    ):
        if path.exists():
            arc.gaps.append({"source": label, "reason": f"exists at {path} and was not scanned as jeremy"})
        else:
            readable = os.access(path.parent, os.R_OK)
            arc.gaps.append(
                {
                    "source": label,
                    "reason": "not present" if readable else f"parent {path.parent} is not readable by this user",
                }
            )
    nlm = HOME / ".notebooklm-sources"
    if nlm.is_dir():
        files = 0
        nbytes = 0
        for dirpath, dirnames, filenames in os.walk(nlm):
            dirnames[:] = [d for d in dirnames if not d.startswith(".")]
            for name in filenames:
                path = Path(dirpath) / name
                try:
                    st = path.stat()
                except OSError:
                    continue
                if st.st_mtime >= CUTOFF:
                    files += 1
                    nbytes += st.st_size
        arc.gaps.append(
            {
                "source": "notebooklm-sources",
                "reason": f"derived capture left in place at {nlm}: {files} files touched since cutoff, {nbytes} bytes. Not duplicated into this archive.",
            }
        )


def collect_kiro_extra(arc: Archive) -> None:
    spec = HOME / ".kiro" / "spec-sessions"
    if spec.is_dir():
        count = 0
        for dirpath, dirnames, filenames in os.walk(spec):
            for name in filenames:
                if not name.endswith((".jsonl", ".md", ".json")):
                    continue
                src = Path(dirpath) / name
                if arc.mtime_ok(src) and not denied(src) and src.stat().st_size < 20_000_000:
                    dest = Path("kiro") / rel_under(src, HOME / ".kiro")
                    arc.copy_file("kiro", src, str(dest), name, name.endswith(".jsonl"))
                    count += 1
        arc.gaps.append({"source": "kiro", "reason": f"{count} extra spec-session files in window"})


def main() -> None:
    if OUT.exists() and any(OUT.iterdir()):
        raise SystemExit(f"refusing to overwrite non-empty {OUT}")
    OUT.mkdir(parents=True, exist_ok=True)
    os.chmod(OUT, 0o700)
    arc = Archive()
    print("grok", flush=True)
    collect_grok(arc)
    print("claude", flush=True)
    n = collect_jsonl_tree(arc, "claude", HOME / ".claude" / "projects", "claude")
    print(f"  claude files {n}", flush=True)
    print("codex", flush=True)
    n = collect_jsonl_tree(arc, "codex", HOME / ".codex" / "sessions", "codex/sessions")
    n += collect_jsonl_tree(arc, "codex", HOME / ".codex" / "archived_sessions", "codex/archived_sessions")
    print(f"  codex files {n}", flush=True)
    print("omp", flush=True)
    n = collect_jsonl_tree(arc, "omp", HOME / ".omp" / "agent" / "sessions", "omp")
    print(f"  omp files {n}", flush=True)
    print("gemini", flush=True)
    n = collect_jsonl_tree(arc, "gemini", HOME / ".gemini" / "antigravity-cli" / "brain", "gemini/brain")
    print(f"  gemini brain files {n}", flush=True)
    print("kiro", flush=True)
    n = collect_jsonl_tree(arc, "kiro", HOME / ".kiro" / "sessions", "kiro/sessions")
    print(f"  kiro session files {n}", flush=True)
    collect_kiro_extra(arc)
    print("cursor transcripts", flush=True)
    n = collect_jsonl_tree(arc, "cursor", HOME / ".cursor" / "projects", "cursor/projects")
    print(f"  cursor jsonl {n}", flush=True)
    print("cursor db", flush=True)
    collect_cursor_db(arc)
    print("junie", flush=True)
    collect_junie(arc)
    print("hermes", flush=True)
    collect_hermes(arc)
    print("sqlite absence and other stores", flush=True)
    collect_sqlite_absence(arc)
    collect_checked_empty(arc)

    by_source = {}
    for row in arc.rows:
        bucket = by_source.setdefault(
            row["source"],
            {"files": 0, "bytes": 0, "records": 0, "tool_events": 0},
        )
        bucket["files"] += 1
        bucket["bytes"] += row["bytes"]
        bucket["records"] += row["records"]
        bucket["tool_events"] += row["tool_events"]

    summary = {
        "window_start": "2026-10-26T00:00:00Z",
        "collected_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "files": arc.files,
        "bytes": arc.bytes,
        "by_source": by_source,
        "tool_names": {source: names.most_common(40) for source, names in arc.names.items()},
        "notes": arc.gaps,
    }
    (OUT / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    os.chmod(OUT / "summary.json", 0o600)
    with (OUT / "manifest.jsonl").open("w", encoding="utf-8") as handle:
        for row in arc.rows:
            handle.write(json.dumps(row, default=str) + "\n")
    os.chmod(OUT / "manifest.jsonl", 0o600)

    lines = [
        "# Hackathon 2026 conversation archive",
        "",
        "Local conversations and tool-use records written on or after 2026-10-26 00:00 UTC (the Monday the hackathon window starts; today is 2026-11-01).",
        "",
        "This directory is gitignored. Do not `git add -f` it. Copies are redacted for private keys, API-key assignments, and SID1/OIA1 envelopes. Originals stay in each agent's own store.",
        "",
        f"Collected at {summary['collected_at']}. Files: {arc.files}. Bytes: {arc.bytes}.",
        "",
        "## Sources",
        "",
    ]
    for source, bucket in sorted(by_source.items()):
        lines.append(
            f"- {source}: {bucket['files']} files, {bucket['records']} records, {bucket['tool_events']} tool events, {bucket['bytes']} bytes"
        )
    lines.extend(["", "## Checked, not copied", ""])
    for note in arc.gaps:
        lines.append(f"- {note.get('source')}: {note.get('reason')}")
    lines.extend(
        [
            "",
            "A session file that was still being written after the cutoff is copied whole, so it can contain turns from before Monday.",
            "OpenCode and Kilo databases were not copied; they contain credential tables and had no session updated in the window.",
            "The NotebookLM derived capture was left in ~/.notebooklm-sources.",
            "",
        ]
    )
    (OUT / "README.md").write_text("\n".join(lines))
    os.chmod(OUT / "README.md", 0o600)
    print(json.dumps({"files": arc.files, "bytes": arc.bytes, "sources": by_source}, indent=2))


if __name__ == "__main__":
    main()

